package com.alibaba.easyexcel.test.core.util;

import java.io.File;

import com.alibaba.excel.util.FileUtils;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Test that setTempFilePrefix() properly updates derived paths.
 */
public class FileUtilsTest {

    @Test
    public void testSetTempFilePrefixUpdatesPoiFilesPath() {
        String newPrefix = "/tmp/my_custom_prefix_12345" + File.separator;
        FileUtils.setTempFilePrefix(newPrefix);

        // After setting a new temp file prefix, getPoiFilesPath() should
        // return a path based on the NEW prefix, not the stale one from class init.
        String poiFilesPath = FileUtils.getPoiFilesPath();
        Assertions.assertTrue(
            poiFilesPath.startsWith(newPrefix),
            "poiFilesPath should start with the new tempFilePrefix. "
                + "Expected prefix: '" + newPrefix + "', got: '" + poiFilesPath + "'"
        );
    }

    @Test
    public void testSetTempFilePrefixUpdatesCachePath() {
        String newPrefix = "/tmp/my_custom_prefix_67890" + File.separator;
        FileUtils.setTempFilePrefix(newPrefix);

        // After setting a new temp file prefix, getCachePath() should
        // return a path based on the NEW prefix, not the stale one from class init.
        String cachePath = FileUtils.getCachePath();
        Assertions.assertTrue(
            cachePath.startsWith(newPrefix),
            "cachePath should start with the new tempFilePrefix. "
                + "Expected prefix: '" + newPrefix + "', got: '" + cachePath + "'"
        );
    }

    @Test
    public void testSetTempFilePrefixAndGetTempFilePrefixRoundTrip() {
        String newPrefix = "/tmp/my_custom_prefix_rt" + File.separator;
        FileUtils.setTempFilePrefix(newPrefix);

        // The prefix itself should be returned correctly
        Assertions.assertEquals(newPrefix, FileUtils.getTempFilePrefix());
    }
}

