package com.alibaba.easyexcel.test.core.csv;

import java.io.StringWriter;

import com.alibaba.excel.metadata.csv.CsvSheet;
import com.alibaba.excel.metadata.csv.CsvWorkbook;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Test for CsvSheet.getPhysicalNumberOfRows() correctness.
 */
public class CsvSheetPhysicalRowsTest {

    @Test
    public void testGetPhysicalNumberOfRowsSingleRow() {
        StringWriter out = new StringWriter();
        CsvWorkbook workbook = new CsvWorkbook(out, java.util.Locale.getDefault(), false, false,
            java.nio.charset.StandardCharsets.UTF_8, false);
        CsvSheet sheet = (CsvSheet) workbook.createSheet();

        sheet.createRow(0);

        int physicalRows = sheet.getPhysicalNumberOfRows();
        Assertions.assertEquals(1, physicalRows, "After creating 1 row, getPhysicalNumberOfRows should return 1");
    }

    @Test
    public void testGetPhysicalNumberOfRowsMultipleRows() {
        StringWriter out = new StringWriter();
        CsvWorkbook workbook = new CsvWorkbook(out, java.util.Locale.getDefault(), false, false,
            java.nio.charset.StandardCharsets.UTF_8, false);
        CsvSheet sheet = (CsvSheet) workbook.createSheet();

        sheet.createRow(0);
        sheet.createRow(1);
        sheet.createRow(2);

        int physicalRows = sheet.getPhysicalNumberOfRows();
        Assertions.assertEquals(3, physicalRows, "After creating 3 rows, getPhysicalNumberOfRows should return 3");
    }

    @Test
    public void testGetPhysicalNumberOfRowsNoRows() throws Exception {
        StringWriter out = new StringWriter();
        CsvWorkbook workbook = new CsvWorkbook(out, java.util.Locale.getDefault(), false, false,
            java.nio.charset.StandardCharsets.UTF_8, false);
        CsvSheet sheet = (CsvSheet) workbook.createSheet();

        // No rows created - lastRowIndex should be -1
        // getPhysicalNumberOfRows should return 0 when no rows created
        // After close, lastRowIndex is still -1, rowCache is empty (size 0)
        // -1 - 0 = -1 which is wrong, should be 0
        sheet.close();
        int physicalRows = sheet.getPhysicalNumberOfRows();
        Assertions.assertTrue(physicalRows >= 0, "getPhysicalNumberOfRows should not be negative: " + physicalRows);
    }

    @Test
    public void testGetPhysicalNumberOfRowsConsistentWithGetLastRowNum() {
        StringWriter out = new StringWriter();
        CsvWorkbook workbook = new CsvWorkbook(out, java.util.Locale.getDefault(), false, false,
            java.nio.charset.StandardCharsets.UTF_8, false);
        CsvSheet sheet = (CsvSheet) workbook.createSheet();

        sheet.createRow(0);
        sheet.createRow(1);

        int physicalRows = sheet.getPhysicalNumberOfRows();
        int lastRowNum = sheet.getLastRowNum();

        // getPhysicalNumberOfRows should be lastRowNum + 1 (0-indexed rows)
        Assertions.assertEquals(lastRowNum + 1, physicalRows,
            "getPhysicalNumberOfRows should equal getLastRowNum() + 1");
    }
}

