package com.alibaba.easyexcel.test.core.dataformat;

import java.math.BigDecimal;
import java.util.Locale;

import com.alibaba.excel.util.NumberDataFormatterUtils;

import lombok.extern.slf4j.Slf4j;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Test for NumberDataFormatterUtils ThreadLocal cache bug.
 * The bug: DataFormatter is cached in ThreadLocal without cache key for locale.
 * Once created with one locale, subsequent calls with different locale reuse the cached formatter.
 */
@Slf4j
public class NumberDataFormatterUtilsTest {

    /**
     * Test that different locales produce different formatted output.
     *
     * The bug: NumberDataFormatterUtils caches DataFormatter in ThreadLocal
     * without considering locale differences. After calling with Locale.US,
     * a subsequent call with Locale.FRANCE will still use the US formatter.
     */
    @Test
    public void testLocaleCaching() {
        // "mmmm" = full month name (e.g., "January" vs "janvier")
        String dataFormatString = "mmmm";
        // Format 16 (0x10) is an internal date format so isADateFormat returns true.
        Short dataFormat = Short.valueOf((short) 16);

        // Excel date 42937 = July 1, 2017 (days since 1900-01-01)
        BigDecimal data = BigDecimal.valueOf(42937);

        // Clear cache so the first call creates a new formatter
        NumberDataFormatterUtils.removeThreadLocalCache();

        // First call with US locale -> English month name
        String usResult = NumberDataFormatterUtils.format(data, dataFormat, dataFormatString,
                null, Locale.US, null);
        log.info("US result: '{}'", usResult);

        // Second call with French locale -> French month name
        String frResult = NumberDataFormatterUtils.format(data, dataFormat, dataFormatString,
                null, Locale.FRANCE, null);
        log.info("FR result: '{}'", frResult);

        // Debug
        log.info("usResult equals frResult: {}", usResult.equals(frResult));

        // CORRECT behavior: different locales produce different output.
        // BUG: both return the same English month name because the cached DataFormatter
        // ignores the new locale parameter.
        Assertions.assertTrue(!usResult.equals(frResult),
                "Locale-sensitive format must produce different results. "
                + "US='" + usResult + "' FR='" + frResult
                + "'. Same result means ThreadLocal cache ignored the locale.");

        // Clean up
        NumberDataFormatterUtils.removeThreadLocalCache();
    }

    /**
     * Test that useScientificFormat parameter changes are respected.
     */
    @Test
    public void testScientificFormatCaching() {
        // First call with scientific format OFF
        NumberDataFormatterUtils.removeThreadLocalCache();
        String noScientific = NumberDataFormatterUtils.format(
                new BigDecimal("1234567.89"),
                Short.valueOf((short) 0), "General",
                null, Locale.US, false);

        // Second call with scientific format ON
        String withScientific = NumberDataFormatterUtils.format(
                new BigDecimal("1234567.89"),
                Short.valueOf((short) 0), "General",
                null, Locale.US, true);

        // These should be different when scientific format is enabled
        Assertions.assertTrue(!noScientific.equals(withScientific),
                "Different scientific format settings should produce different results");

        // Clean up ThreadLocal for other tests
        NumberDataFormatterUtils.removeThreadLocalCache();
    }
}

