package com.alibaba.easyexcel.test.core.merge;

import com.alibaba.excel.write.merge.LoopMergeStrategy;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for LoopMergeStrategy constructor validation.
 * The validation uses < 1 (allows value=1) but error messages say "must be greater than 1"
 * which is misleading since 1 IS allowed.
 */
public class LoopMergeStrategyTest {

    @Test
    public void eachRowOneShouldBeAllowedWhenColumnExtendGreaterThanOne() {
        // eachRow=1 should be allowed by validation (condition is eachRow < 1)
        // when columnExtend > 1. The 2-arg constructor sets columnExtend=1, triggering the both=1 check.
        // The error message claims "must be greater than 1" which contradicts the actual validation
        assertDoesNotThrow(() -> new LoopMergeStrategy(1, 2, 0),
                "eachRow=1 should be valid when columnExtend>1 since the check is eachRow < 1");
    }

    @Test
    public void columnExtendOneShouldBeAllowed() {
        // columnExtend=1 should also be allowed (condition is columnExtend < 1)
        assertDoesNotThrow(() -> new LoopMergeStrategy(2, 1, 0),
                "columnExtend=1 should be valid since the check is columnExtend < 1");
    }

    @Test
    public void bothOneShouldThrow() {
        // eachRow=1 && columnExtend=1 should throw (explicit check on line 39)
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(1, 1, 0));
        // This is expected: one of them must be > 1
    }

    @Test
    public void eachRowZeroErrorMessageShouldNotClaimGreaterThanOne() {
        // When eachRow=0 throws, the message should NOT say "greater than 1"
        // since 1 is actually valid. The message is misleading.
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(0, 2, 0));
        // The message says "EachRows must be greater than 1" but 1 IS allowed
        assertFalse(e.getMessage().contains("greater than 1"),
                "Error message should not say 'greater than 1' when value=1 is actually valid. Message was: " + e.getMessage());
    }

    @Test
    public void columnExtendZeroErrorMessageShouldNotClaimGreaterThanOne() {
        // When columnExtend=0 throws, the message should NOT say "greater than 1"
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(2, 0, 0));
        assertFalse(e.getMessage().contains("greater than 1"),
                "Error message should not say 'greater than 1' when value=1 is actually valid. Message was: " + e.getMessage());
    }

    @Test
    public void negativeEachRowShouldThrow() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(-1, 2, 0));
        assertEquals("EachRows must be greater than 1", e.getMessage());
    }

    @Test
    public void negativeColumnExtendShouldThrow() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(2, -1, 0));
        assertEquals("ColumnExtend must be greater than 1", e.getMessage());
    }

    @Test
    public void negativeColumnIndexShouldThrow() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> new LoopMergeStrategy(2, 2, -1));
        assertEquals("ColumnIndex must be greater than 0", e.getMessage());
    }
}

