        // Correct: columnWidth should be 2*256 = 512 (based on character count)
        File cjkFile = TestFileUtil.createNewFile("cjkColumnWidth.xlsx");

        String cjkHead = "你好";
        int charLength = cjkHead.length(); // 2
        EasyExcel.write(cjkFile, CjkData.class)
