        // Column width should equal character length * 256, not byte length * 256
        // In UTF-8: "你好" = 6 bytes but only 2 characters
        int actualWidth = sheet.getColumnWidth(0);
        System.out.println("Actual column width: " + actualWidth);
        System.out.println("Expected (char-based): " + charLength * 256);
        System.out.println("Default charset: " + Charset.defaultCharset());
        System.out.println("Byte length of '你好': " + cjkHead.getBytes().length);
        Assertions.assertEquals(charLength * 256, actualWidth,
