package com.alibaba.easyexcel.test.core.converter;

import java.math.BigDecimal;

import com.alibaba.excel.converters.WriteConverterContext;
import com.alibaba.excel.converters.bigdecimal.BigDecimalBooleanConverter;
import com.alibaba.excel.converters.floatconverter.FloatNumberConverter;
import com.alibaba.excel.metadata.data.WriteCellData;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * @author Jiaju Zhuang
 */
@TestMethodOrder(MethodOrderer.MethodName.class)
public class ConverterTest {

    @Test
    public void t01FloatNumberConverter() {
        FloatNumberConverter floatNumberConverter = new FloatNumberConverter();
        WriteConverterContext<Float> context = new WriteConverterContext<>();
        context.setValue(95.62F);
        WriteCellData<?> writeCellData = floatNumberConverter.convertToExcelData(context);
        Assertions.assertEquals(0, writeCellData.getNumberValue().compareTo(new BigDecimal("95.62")));
    }

    @Test
    public void t02BigDecimalBooleanConverterWithScale() {
        BigDecimalBooleanConverter converter = new BigDecimalBooleanConverter();

        // BigDecimal("1.00") is numerically equal to 1 but has scale 2
        // It should still be converted to Boolean.TRUE
        WriteCellData<?> result = converter.convertToExcelData(new BigDecimal("1.00"), null, null);
        Assertions.assertEquals(Boolean.TRUE, result.getBooleanValue(),
            "BigDecimal 1.00 should convert to Boolean.TRUE");

        // BigDecimal("1.0") has scale 1
        result = converter.convertToExcelData(new BigDecimal("1.0"), null, null);
        Assertions.assertEquals(Boolean.TRUE, result.getBooleanValue(),
            "BigDecimal 1.0 should convert to Boolean.TRUE");

        // BigDecimal.ONE (scale 0) should work
        result = converter.convertToExcelData(BigDecimal.ONE, null, null);
        Assertions.assertEquals(Boolean.TRUE, result.getBooleanValue(),
            "BigDecimal.ONE should convert to Boolean.TRUE");

        // Zero should convert to FALSE
        result = converter.convertToExcelData(BigDecimal.ZERO, null, null);
        Assertions.assertEquals(Boolean.FALSE, result.getBooleanValue(),
            "BigDecimal.ZERO should convert to Boolean.FALSE");

        // Other non-zero values should convert to FALSE (only exactly 1 -> TRUE)
        result = converter.convertToExcelData(new BigDecimal("2"), null, null);
        Assertions.assertEquals(Boolean.FALSE, result.getBooleanValue(),
            "BigDecimal 2 should convert to Boolean.FALSE");
    }

}

