package com.alibaba.easyexcel.test.core.util;

import com.alibaba.excel.util.IoUtils;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link IoUtils}.
 */
class IoUtilsTest {

    /**
     * Verify that IoUtils.toByteArray(InputStream) closes the input stream.
     * The method uses a try-finally pattern; the finally block should close
     * the input stream to prevent resource leaks when callers don't close it.
     */
    @Test
    void toByteArrayShouldCloseInputStream() throws IOException {
        byte[] data = "hello world".getBytes();
        boolean[] closed = {false};

        InputStream trackingStream = new ByteArrayInputStream(data) {
            @Override
            public void close() throws IOException {
                closed[0] = true;
                super.close();
            }
        };

        byte[] result = IoUtils.toByteArray(trackingStream);

        assertArrayEquals(data, result, "toByteArray should return the correct bytes");
        assertTrue(closed[0], "IoUtils.toByteArray should close the input stream in its finally block");
    }

    /**
     * Verify that IoUtils.toByteArray(InputStream) closes the input stream
     * even when an IOException occurs during copy.
     */
    @Test
    void toByteArrayShouldCloseInputStreamOnError() throws Exception {
        InputStream throwingStream = new InputStream() {
            private int count = 0;

            @Override
            public int read() throws IOException {
                return 'a'; // Return some data
            }

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                if (count++ < 2) {
                    // Return some data first
                    System.arraycopy("partial".getBytes(), 0, b, off, Math.min(len, 7));
                    return Math.min(len, 7);
                } else {
                    throw new IOException("Simulated read failure");
                }
            }

            @Override
            public void close() throws IOException {
                // Stream should still be closed on error
            }
        };

        boolean[] closed = {false};
        InputStream trackingStream = new InputStream() {
            @Override
            public int read() throws IOException {
                return throwingStream.read();
            }

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                return throwingStream.read(b, off, len);
            }

            @Override
            public void close() throws IOException {
                closed[0] = true;
                super.close();
            }
        };

        try {
            IoUtils.toByteArray(trackingStream);
            fail("Should throw IOException");
        } catch (IOException e) {
            // Expected
        }

        assertTrue(closed[0], "IoUtils.toByteArray should close the input stream even on error");
    }
}

