package com.alibaba.easyexcel.test.core.csv;

import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.util.Locale;

import com.alibaba.excel.metadata.csv.CsvWorkbook;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Tests for CsvWorkbook's cell style methods.
 */
public class CsvWorkbookCellStyleTest {

    /**
     * According to Apache POI's Workbook interface, getNumCellStyles() should return
     * the number of cell styles created. When no styles have been created yet, it
     * should return 0 — not throw a NullPointerException.
     *
     * This test verifies that calling getNumCellStyles() before any call to
     * createCellStyle() returns 0 instead of throwing NPE due to a lazily
     * initialized csvCellStyleList being null.
     */
    @Test
    public void getNumCellStylesBeforeCreateCellStyleShouldReturnZero() {
        CsvWorkbook workbook = new CsvWorkbook(
                new StringWriter(),
                Locale.US,
                false,
                false,
                StandardCharsets.UTF_8,
                true
        );

        // Before any createCellStyle() call, csvCellStyleList is null.
        // getNumCellStyles() should return 0, not throw NPE.
        int numStyles = workbook.getNumCellStyles();
        Assertions.assertEquals(0, numStyles,
                "getNumCellStyles() should return 0 when no cell styles have been created");
    }

    /**
     * getCellStyleAt() should also handle the case where csvCellStyleList is null.
     * Calling it before any createCellStyle() should return null for any index.
     */
    @Test
    public void getCellStyleAtBeforeCreateCellStyleShouldReturnNull() {
        CsvWorkbook workbook = new CsvWorkbook(
                new StringWriter(),
                Locale.US,
                false,
                false,
                StandardCharsets.UTF_8,
                true
        );

        // Before any createCellStyle() call, csvCellStyleList is null.
        // getCellStyleAt(0) should return null, not throw NPE.
        Object style = workbook.getCellStyleAt(0);
        Assertions.assertNull(style,
                "getCellStyleAt(0) should return null when no cell styles have been created");
    }

    /**
     * After creating a cell style, getNumCellStyles() should return the correct count.
     */
    @Test
    public void getNumCellStylesAfterCreateCellStyleShouldReturnCount() {
        CsvWorkbook workbook = new CsvWorkbook(
                new StringWriter(),
                Locale.US,
                false,
                false,
                StandardCharsets.UTF_8,
                true
        );

        workbook.createCellStyle();
        workbook.createCellStyle();

        int numStyles = workbook.getNumCellStyles();
        Assertions.assertEquals(2, numStyles,
                "getNumCellStyles() should return 2 after two createCellStyle() calls");
    }
}

