package com.alibaba.easyexcel.test.core.cache;

import java.io.ByteArrayInputStream;
import java.io.IOException;

import com.alibaba.excel.cache.selector.SimpleReadCacheSelector;

import org.apache.poi.openxml4j.opc.PackagePart;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

/**
 * Test for {@link SimpleReadCacheSelector} resource leak fix.
 */
public class SimpleReadCacheSelectorTest {

    /**
     * A ByteArrayInputStream subclass that tracks whether close() was called.
     */
    static class TrackableInputStream extends ByteArrayInputStream {
        private boolean closed = false;

        public TrackableInputStream(byte[] buf) {
            super(buf);
        }

        @Override
        public void close() throws IOException {
            this.closed = true;
            super.close();
        }

        public boolean isClosed() {
            return this.closed;
        }
    }

    /**
     * Verify that SimpleReadCacheSelector closes the InputStream obtained via
     * getInputStream() when PackagePart.getSize() returns a negative value.
     * <p>
     * Correct behavior: the InputStream MUST be closed after reading its size,
     * otherwise every invocation leaks a file descriptor / stream handle.
     * <p>
     * This test FAILS on the buggy code (close is never called) and PASSES
     * once the bug is fixed (close is called in a try-with-resources or finally).
     */
    @Test
    public void readCache_shouldCloseInputStream_whenGetSizeReturnsNegative() throws Exception {
        // Arrange
        TrackableInputStream trackableStream = new TrackableInputStream("dummy content".getBytes());
        PackagePart mockPart = Mockito.mock(PackagePart.class);

        // size < 0 triggers the getInputStream() path
        Mockito.when(mockPart.getSize()).thenReturn(-1L);
        Mockito.when(mockPart.getInputStream()).thenReturn(trackableStream);

        SimpleReadCacheSelector selector = new SimpleReadCacheSelector();

        // Act
        selector.readCache(mockPart);

        // Assert: the InputStream must be closed — correct behavior the bug violates
        Assertions.assertTrue(
            trackableStream.isClosed(),
            "InputStream obtained from PackagePart.getInputStream() was not closed — resource leak"
        );
    }
}

