/**
 * Test that EasyExcel can read data using model classes with non-public default constructors.
 * Class.newInstance() (deprecated since Java 9) fails for non-public constructors,
 * while getDeclaredConstructor().newInstance() works correctly.
 */
public class NonPublicConstructorDataTest {

    private static File file;

    static {
        file = TestFileUtil.createNewFile("nonPublicConstructor.xlsx");
    }

    /**
     * Model class with a package-private (non-public) default constructor.
     * Class.newInstance() throws IllegalAccessException for this.
     * getDeclaredConstructor().newInstance() should work fine.
     */
    @Getter
    @Setter
    static class PackagePrivateConstructorData {
        @ExcelProperty("name")
        private String name;

        // Package-private constructor (not public)
        PackagePrivateConstructorData() {
        }
    }

    /**
     * Model class with a protected default constructor.
     * Class.newInstance() throws IllegalAccessException for this too.
     */
    @Getter
    @Setter
    static class ProtectedConstructorData {
        @ExcelProperty("name")
        private String name;

        // Protected constructor (not public)
        protected ProtectedConstructorData() {
        }
    }

    @Test
    public void t01ReadPackagePrivateConstructor() {
