        List<PackagePrivateConstructorData> dataList = new ArrayList<>();
        PackagePrivateConstructorData data1 = new PackagePrivateConstructorData();
        data1.setName("test name");
        dataList.add(data1);
        EasyExcel.write(file, PackagePrivateConstructorData.class).sheet().doWrite(dataList);

        // Read data back - this should succeed with getDeclaredConstructor().newInstance()
        // but fails with Class.newInstance() which requires a public constructor
