                @Override
                public void doAfterAllAnalysed(AnalysisContext context) {
                }
            }).sheet().doRead();

        Assertions.assertEquals(1, readData.size());
        Assertions.assertEquals("test name", readData.get(0).getName());
    }

    @Test
    public void t02ReadProtectedConstructor() {
