import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

/**
 * Regression tests for BooleanUtils.valueOf(String).
 *
 * The correct behaviour follows standard Java convention (Boolean.parseBoolean):
 * "true" (case-insensitive) should yield Boolean.TRUE.
 */
class BooleanUtilsTest {

    @Test
    void valueOf_trueLowercase_shouldReturnTrue() {
        // Boolean.parseBoolean("true") == true, so valueOf("true") must return Boolean.TRUE
        assertEquals(Boolean.TRUE, BooleanUtils.valueOf("true"),
                "valueOf(\"true\") should return Boolean.TRUE, consistent with Boolean.parseBoolean");
    }

    @Test
    void valueOf_trueUppercase_shouldReturnTrue() {
        assertEquals(Boolean.TRUE, BooleanUtils.valueOf("TRUE"),
                "valueOf(\"TRUE\") should return Boolean.TRUE, consistent with Boolean.parseBoolean");
    }

    @Test
