package com.alibaba.easyexcel.test.core.annotation;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import com.alibaba.easyexcel.test.util.TestFileUtil;
import com.alibaba.excel.EasyExcel;
import com.alibaba.excel.annotation.ExcelProperty;
import com.alibaba.excel.exception.ExcelCommonException;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

/**
 * Annotation data test
 *
 * @author Jiaju Zhuang
 */
@TestMethodOrder(MethodOrderer.MethodName.class)
public class AnnotationIndexAndNameDataTest {

    private static File file07;
    private static File file03;
    private static File fileCsv;

    @BeforeAll
    public static void init() {
        file07 = TestFileUtil.createNewFile("annotationIndexAndName07.xlsx");
        file03 = TestFileUtil.createNewFile("annotationIndexAndName03.xls");
        fileCsv = TestFileUtil.createNewFile("annotationIndexAndNameCsv.csv");
    }

    @Test
    public void t01ReadAndWrite07() {
        readAndWrite(file07);
    }

    @Test
    public void t02ReadAndWrite03() {
        readAndWrite(file03);
    }

    @Test
    public void t03ReadAndWriteCsv() {
        readAndWrite(fileCsv);
    }

    private void readAndWrite(File file) {
        EasyExcel.write(file, AnnotationIndexAndNameData.class).sheet().doWrite(data());
        EasyExcel.read(file, AnnotationIndexAndNameData.class, new AnnotationIndexAndNameDataListener()).sheet()
            .doRead();
    }

    private List<AnnotationIndexAndNameData> data() {
        List<AnnotationIndexAndNameData> list = new ArrayList<AnnotationIndexAndNameData>();
        AnnotationIndexAndNameData data = new AnnotationIndexAndNameData();
        data.setIndex0("第0个");
        data.setIndex1("第1个");
        data.setIndex2("第2个");
        data.setIndex4("第4个");
        list.add(data);
        return list;
    }

    /**
     * When two fields declare the same @ExcelProperty(index), the error message
     * must NOT use the word "inconsistent", which is semantically wrong. The
     * indices are the SAME (conflicting), so the message should indicate that
     * they are conflicting/duplicated, not that they "must be inconsistent".
     */
    @Test
    public void t04DuplicateIndexErrorMessage() {
        File file = TestFileUtil.createNewFile("duplicateIndexError.xlsx");
        ExcelCommonException ex = Assertions.assertThrows(ExcelCommonException.class,
                () -> EasyExcel.write(file, DuplicateIndexData.class).sheet().doWrite(List.of()));
        String message = ex.getMessage();
        // The word "inconsistent" is semantically wrong here — the indices ARE
        // consistent (they are the same), that is why it is an error.
        Assertions.assertFalse(
                message.toLowerCase().contains("inconsistent"),
                "Error message should not say 'must be inconsistent' when two fields "
                        + "have the same index. Got: " + message);
    }

    /**
     * Data class with two fields declaring the same index — should trigger the
     * duplicate-index error in ClassUtils.declaredOneField().
     */
    public static class DuplicateIndexData {
        @ExcelProperty(index = 0)
        private String fieldA;

        @ExcelProperty(index = 0)
        private String fieldB;
    }
}

