package com.alibaba.easyexcel.test.core.merge;

import com.alibaba.excel.write.merge.OnceAbsoluteMergeStrategy;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link OnceAbsoluteMergeStrategy} validation and construction.
 *
 * @author Test author
 */
public class OnceAbsoluteMergeStrategyTest {

    @Test
    public void t01ZeroValuesShouldBeAccepted() {
        // Excel row/column indices start at 0, so 0 is a valid index.
        // The constructor should NOT throw when all parameters are 0.
        assertDoesNotThrow(() -> new OnceAbsoluteMergeStrategy(0, 0, 0, 0),
            "OnceAbsoluteMergeStrategy should accept 0 as a valid row/column index");
    }

    @Test
    public void t02NegativeValuesShouldBeRejected() {
        // Negative indices are invalid and should be rejected.
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
            () -> new OnceAbsoluteMergeStrategy(-1, 0, 0, 0),
            "Should throw for negative firstRowIndex");
        assertEquals("All parameters must be greater than or equal to 0", ex.getMessage(),
            "Error message should accurately state that parameters must be >= 0, not > 0");
    }

    @Test
    public void t03ZeroIsValidForMixedParameters() {
        // Mix of 0 and positive values should work fine.
        assertDoesNotThrow(() -> new OnceAbsoluteMergeStrategy(0, 10, 0, 5),
            "OnceAbsoluteMergeStrategy should accept 0 mixed with positive indices");
    }
}

